{
  "findings": [
    {
      "check_id": "CKV_AWS_79",
      "title": "Instance Metadata Service Version 1 (IMDSv1) is enabled by default",
      "resource": "aws_launch_template.changeme_simple_asg_launch_template_nlb",
      "severity": "MEDIUM",
      "explanation": "The launch template does not configure metadata_options, so EC2 instances will allow unauthenticated access to the Instance Metadata Service (IMDSv1). This exposes instance credentials and user data to Server-Side Request Forgery (SSRF) attacks."
    }
  ],
  "patched_code": "resource \"aws_launch_template\" \"changeme_simple_asg_launch_template_nlb\" {\n  name                   = \"changeme-simple-asg-launch-template-nlb\"\n  image_id               = data.aws_ami.changeme_amazon_nlb_ami.id\n  instance_type          = \"t2.micro\"\n  vpc_security_group_ids = [aws_security_group.changeme_nlb_aws_security_group.id]\n  user_data              = filebase64(\"${path.module}/user_data.sh\")\n\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n}",
  "fix_summary": "Added a metadata_options block to the aws_launch_template resource with http_tokens set to 'required' to enforce IMDSv2 and disable the less secure IMDSv1 protocol."
}
